const j = $json;
return {
  json: {
    posting_id: j.posting_id,
    company: j.company,
    role: j.role,
    location: j.location,
    employment_type: j.employment_type,
    apply_url: j.apply_url,
    match_score: j.match_score,
    reason: j.reason,
    missing_skills_text: Array.isArray(j.missing_skills) ? j.missing_skills.join(', ') : '',
    deadline: j.deadline || null,
    eligibility: j.eligibility || null,
    ctc_or_stipend: j.ctc_or_stipend || null
  }
};

function ordinal(n) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

function formatDeadline(raw) {
  if (!raw) return 'Not stated';
  // Only reformat if raw parses as an unambiguous ISO-like date (YYYY-MM-DD).
  // Free text like 'Rolling' or 'Open until filled' must pass through as-is.
  if (!/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  const d = new Date(raw + 'T00:00:00Z');
  if (isNaN(d.getTime())) return raw;
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  return `${ordinal(d.getUTCDate())} ${months[d.getUTCMonth()]}, ${d.getUTCFullYear()}`;
}

const j = $json;
const score = j.match_score;
const color = score >= 90 ? 3066993 : (score >= 80 ? 15844367 : 15105570);

const lines = [
  j.reason || '',
  '',
  `**Score:** ${score}/100`,
  `**Location:** ${j.location || 'Not specified'}`,
  `**Type:** ${j.employment_type || 'Not specified'}`,
  `**Deadline:** ${formatDeadline(j.deadline)}`,
  `**Eligibility:** ${j.eligibility || 'Not stated'}`,
  `**CTC/Stipend:** ${j.ctc_or_stipend || 'Not stated'}`
];
if (j.missing_skills_text) lines.push(`**Missing skills:** ${j.missing_skills_text}`);
lines.push(`**Apply:** ${j.apply_url}`);

return {
  json: {
    title: `${j.company} — ${j.role}`,
    description: lines.join('\n'),
    color,
    url: j.apply_url
  }
};

const received = $('Prepare Notification').all().length;
const sent = $input.all().length;
return [{ json: { received, sent } }];
